def left_pattern_cell(col, distance):
    """Generate left pattern value at given column for given distance from horizon"""
    patterns = {
        4: [4, 0, 4, 4, 4, 4],
        3: [4, 0, 4, 0, 0, 0],
        2: [4, 0, 4, 0, 4, 4],
        1: [4, 0, 4, 0, 4, 0],
    }
    if distance in patterns:
        return patterns[distance][col]
    # Extrapolate for other distances
    if col in [0, 2, 4]:
        return 4
    if col == 1:
        return 0
    # Column 3
    if distance >= 3:
        return patterns[4][3] if 3 < len(patterns[4]) else 0
    else:
        return patterns[3][3] if 3 < len(patterns[3]) else 0

